// lib/router/app_router.dart

import 'package:go_router/go_router.dart';
import 'package:flutter/material.dart';

// Экрандарымызды импорттаймыз
import '../screens/home_screen.dart';
import '../screens/profile_screen.dart';
import '../screens/settings_screen.dart';

// Роутер жасаймыз
final GoRouter appRouter = GoRouter(
  // Бастапқы маршрут
  initialLocation: '/',

  // Отладка логтарын қосу (әзірлеу үшін)
  debugLogDiagnostics: true,

  // Маршруттар тізімі
  routes: [
    // Басты бет
    GoRoute(
      path: '/',
      name: 'home',
      builder: (context, state) => const HomeScreen(),
    ),

    // Профиль беті
    GoRoute(
      path: '/profile',
      name: 'profile',
      builder: (context, state) => const ProfileScreen(),
    ),

    // Параметрлер беті
    GoRoute(
      path: '/settings',
      name: 'settings',
      builder: (context, state) => const SettingsScreen(),
    ),
  ],
);

import 'package:flutter/material.dart';
import 'package:go_router/go_router.dart';

class HomeScreen extends StatelessWidget {
  const HomeScreen({super.key});

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        title: const Text('Басты бет'),
      ),
      body: Center(
        child: Column(
          mainAxisAlignment: MainAxisAlignment.center,
          children: [
            // Профильге өту батырмасы
            ElevatedButton(
              onPressed: () {
                // Профиль бетіне өтеміз
                context.go('/profile');
              },
              child: const Text('Профильді ашу'),
            ),

            const SizedBox(height: 16),

            // push батырмасы (стекке қосады)
            ElevatedButton(
              onPressed: () {
                // Стекке бет қосамыз
                context.push('/settings');
              },
              child: const Text('Параметрлер (push)'),
            ),

            const SizedBox(height: 16),

            // Атау бойынша навигация
            ElevatedButton(
              onPressed: () {
                context.goNamed('profile');
              },
              child: const Text('Профиль (атау бойынша)'),
            ),
          ],
        ),
      ),
    );
  }
}

