// Параметрлермен толық мысал

final GoRouter appRouter = GoRouter(
  routes: [
    // Басты бет
    GoRoute(
      path: '/',
      name: 'home',
      builder: (context, state) => const HomeScreen(),
    ),

    // Тауарлар тізімі
    GoRoute(
      path: '/products',
      name: 'products',
      builder: (context, state) => const ProductsListScreen(),
    ),

    // ID параметрі бар тауар беті
    GoRoute(
      path: '/products/:id',
      name: 'product',
      builder: (context, state) {
        // URL-ден ID аламыз
        final id = state.pathParameters['id']!;
        return ProductScreen(productId: id);
      },
    ),

    // Query параметрлері бар іздеу
    GoRoute(
      path: '/search',
      name: 'search',
      builder: (context, state) {
        final query = state.uri.queryParameters['query'] ?? '';
        return SearchScreen(searchQuery: query);
      },
    ),
  ],
);

// Кодта қолдану:

// ID 42 бар тауарға өту
context.go('/products/42');

// goNamed арқылы дәл солай
context.goNamed('product', pathParameters: {'id': '42'});

// Параметрлермен іздеу
context.go('/search?query=телефон');
context.goNamed('search', queryParameters: {'query': 'телефон'});

// Кірістірілген маршруттар мысалы

final GoRouter appRouter = GoRouter(
  initialLocation: '/',
  routes: [
    // Басты бет
    GoRoute(
      path: '/',
      name: 'home',
      builder: (context, state) => const HomeScreen(),
    ),

    // Кірістірілген маршруттары бар профиль
    GoRoute(
      path: '/profile',
      name: 'profile',
      builder: (context, state) => const ProfileScreen(),

      // Кірістірілген маршруттар
      routes: [
        // /profile/personal
        GoRoute(
          path: 'personal',
          name: 'personal-data',
          builder: (context, state) => const PersonalDataScreen(),
        ),

        // /profile/settings
        GoRoute(
          path: 'settings',
          name: 'profile-settings',
          builder: (context, state) => const ProfileSettingsScreen(),
        ),

        // /profile/orders
        GoRoute(
          path: 'orders',
          name: 'orders-history',
          builder: (context, state) => const OrdersHistoryScreen(),
        ),

        // /profile/orders/:id - нақты тапсырыс
        GoRoute(
          path: 'orders/:orderId',
          name: 'order-details',
          builder: (context, state) {
            final orderId = state.pathParameters['orderId']!;
            return OrderDetailsScreen(orderId: orderId);
          },
        ),
      ],
    ),
  ],
);

