// === lib/router/app_router.dart ===

import 'package:flutter/material.dart';
import 'package:go_router/go_router.dart';

// Маршруттарды анықтаймыз
final GoRouter appRouter = GoRouter(
  initialLocation: '/',
  debugLogDiagnostics: true,

  routes: [
    // Басты бет
    GoRoute(
      path: '/',
      name: 'home',
      builder: (context, state) => const HomeScreen(),
    ),

    // Тауарлар тізімі
    GoRoute(
      path: '/products',
      name: 'products',
      builder: (context, state) => const ProductsScreen(),

      // Тауар егжей-тегжейлері үшін кірістірілген маршрут
      routes: [
        GoRoute(
          path: ':id',
          name: 'product-detail',
          builder: (context, state) {
            final id = state.pathParameters['id']!;
            return ProductDetailScreen(productId: id);
          },
        ),
      ],
    ),

    // Профиль
    GoRoute(
      path: '/profile',
      name: 'profile',
      builder: (context, state) => const ProfileScreen(),
    ),
  ],

  // Қате беті
  errorBuilder: (context, state) => ErrorScreen(error: state.error),
);

// === lib/main.dart ===

import 'package:flutter/material.dart';
import 'router/app_router.dart';

void main() {
  runApp(const MyApp());
}

class MyApp extends StatelessWidget {
  const MyApp({super.key});

  @override
  Widget build(BuildContext context) {
    return MaterialApp.router(
      title: 'Тауарлар каталогы',
      theme: ThemeData(
        colorScheme: ColorScheme.fromSeed(seedColor: Colors.blue),
        useMaterial3: true,
      ),
      routerConfig: appRouter,
    );
  }
}

// === Тауарлар экраны мысалы ===

class ProductsScreen extends StatelessWidget {
  const ProductsScreen({super.key});

  @override
  Widget build(BuildContext context) {
    final products = [
      {'id': '1', 'name': 'iPhone 15'},
      {'id': '2', 'name': 'Samsung Galaxy'},
      {'id': '3', 'name': 'Google Pixel'},
    ];

    return Scaffold(
      appBar: AppBar(title: const Text('Тауарлар')),
      body: ListView.builder(
        itemCount: products.length,
        itemBuilder: (context, index) {
          final product = products[index];
          return ListTile(
            title: Text(product['name']!),
            trailing: const Icon(Icons.arrow_forward_ios),
            onTap: () {
              // Тауар егжей-тегжейлеріне өту
              context.go('/products/${product['id']}');
            },
          );
        },
      ),
    );
  }
}
